import os
import zipfile
import xml.etree.ElementTree as ET

print("CWD files:", os.listdir("."))

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx - 1

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    print("ZIP entries:", z.namelist())

    # workbook.xml -> sheet names
    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    rels_xml = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_xml:
        rel_map[rel.get("Id")] = rel.get("Target")

    sheets = []
    for sh in wb_xml.find("m:sheets", NS):
        rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        sheets.append((sh.get("name"), rel_map[rid].lstrip("/")))
    print("Sheets:", sheets)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss_xml = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss_xml.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)
    print("Shared strings count:", len(shared))

    for name, target in sheets:
        print(f"=== Sheet: {name} ===")
        xml = ET.fromstring(z.read("xl/" + target))
        for row in xml.find("m:sheetData", NS):
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                isel = c.find("m:is", NS)
                if v is not None and v.text is not None:
                    val = v.text
                    if t == "s":
                        val = shared[int(val)]
                    elif t == "b":
                        val = val == "1"
                    elif t == "str":
                        pass
                elif isel is not None:
                    val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                else:
                    continue
                print(f"{ref}: {val!r}")
        print()

