import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

with zipfile.ZipFile("budget.xlsx") as z:
    xml = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

rows = {}
for row in xml.find("m:sheetData", NS):
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        v = c.find("m:v", NS)
        if v is not None and v.text is not None:
            rows[ref] = v.text

expenses = []
for r in range(11, 23):  # rows 11..22 are expense line items
    cat = rows.get(f"A{r}")
    name = rows.get(f"B{r}")
    amt = rows.get(f"C{r}")
    expenses.append((cat, name, float(amt)))

by_cat = {}
total = 0.0
for cat, name, amt in expenses:
    by_cat[cat] = by_cat.get(cat, 0.0) + amt
    total += amt

for cat in sorted(by_cat):
    print(f"{cat}: ${by_cat[cat]:,.2f}")
print(f"TOTAL EXPENSES: ${total:,.2f}")

